const aiProvider=m=>{const k=String(m||'');if(k.startsWith('@cf/'))return 'cf';if(k.startsWith('gemini:'))return 'gemini';if(k.startsWith('groq:'))return 'groq';if(k.startsWith('cerebras:'))return 'cerebras';return 'cf'};
